import React, { useEffect, useState } from "react";
import { DataGrid } from "@mui/x-data-grid";
import { makeStyles } from "@mui/styles";
import { Chip } from "@mui/material";
import { SUPPORT_TEAM, TARGET_HOURS } from "./discussionsConfig";

const useStyles = makeStyles({
  red: {
    background: "#FD8369"
  },
  green: {
    background: "#82E0AA"
  },
  grey: {
    background: "#E5E7E9"
  }
});

const team = new Set(SUPPORT_TEAM.map(u => u.toLowerCase()));
const onTeam = (user) => !!user && team.has(user.toLowerCase());

// needs-reply: no reply yet, or someone outside the support team commented last
// waiting-on-user: a support team member commented last
// internal: started by a support team member
const statusOf = (row) => {
  if (onTeam(row.author)) return "internal";
  if (row.initial_answer === "No") return "needs-reply";
  if (onTeam(row.last_commenter)) return "waiting-on-user";
  return "needs-reply";
};

const hoursSince = (iso) => {
  if (!iso) return null;
  const t = Date.parse(iso);
  return Number.isNaN(t) ? null : Math.floor((Date.now() - t) / 36e5);
};

const ItemDataGrid = ({ sources, offRepos = [] }) => {
  const classes = useStyles();
  const [data, setData] = useState([]);
  const [noData, setNoData] = useState([]);
  const [summary, setSummary] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      // Load each repository on its own, so one missing file doesn't
      // blank the whole table.
      const results = await Promise.allSettled(
        sources.map(async (s) => {
          const response = await fetch(s.url);
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          return await response.json();
        })
      );

      const missing = [];
      const counts = [];
      let rows = [];
      results.forEach((r, i) => {
        if (r.status === "fulfilled" && Array.isArray(r.value)) {
          rows = rows.concat(r.value.map(j => ({ ...j, forum: sources[i].label || j.repository })));
          counts.push({ ...sources[i], count: r.value.length });
        } else {
          counts.push({ ...sources[i], count: null });
          missing.push(`${sources[i].owner}/${sources[i].repo}`);
          console.error("No discussions data for", sources[i].url, r.reason);
        }
      });

      rows = rows.map((j, index) => {
        const status = statusOf(j);
        const lastActivity = j.last_comment_date_time || j.iso_date_time;
        return {
          ...j,
          id: index,
          status,
          hours_waiting: status === "needs-reply" ? hoursSince(lastActivity) : null,
        };
      });

      setData(rows);
      setNoData(missing);
      setSummary(counts);
    };

    fetchData();
  }, [sources]);

  const columns = [
    { field: "forum", headerName: "Forum", width: 170 },
    { field: "index", headerName: "GitHub Id", width: 100, renderCell: (params) => (
      <a href={params.row.github_url} target="_blank" rel="noopener noreferrer">{params.value}</a>
    ) },
    { field: "title", headerName: "Title", width: 300 },
    { field: "hours_waiting", headerName: "Waiting", type: "number", width: 150,
      renderCell: (params) => {
        const h = params.value;
        if (h === null || h === undefined) return "";
        const over = h >= TARGET_HOURS.due;
        const text = h >= 72 ? `${Math.floor(h / 24)} days` : `${h} h`;
        return <span style={{ fontWeight: over ? 700 : 400 }}>{text}{over ? " (overdue)" : ""}</span>;
      } },
    { field: "iso_date_time", headerName: "Date Created", width: 170 },
    { field: "initial_answer", headerName: "Initial Answer?", width: 100},
    { field: "author", headerName: "Author", width: 130 },
    { field: "last_comment_date_time", headerName: "Last Comment", width: 170 },
    { field: "last_commenter", headerName: "Last Comment Author", width: 170 },
    {
      field: "category",
      headerName: "Category",
      width: 150,
      renderCell: (params) => (
        <Chip
          label={params.value || "—"}
          size="small"
          sx={{ backgroundColor: "#363636", color: "#FFFFFF" }}
        />
      )
    }
      ];

  const getRowClassName = (params) => {
    switch (params.row.status) {
      case "needs-reply": return classes.red;
      case "waiting-on-user": return classes.green;
      case "internal": return classes.grey;
      default: return "";
    }
  };

  const chip = { display: "inline-block", margin: "0 8px 8px 0", padding: "4px 10px", borderRadius: 14, fontSize: 14, textDecoration: "none", border: "1px solid #d9e2ec" };
  return (
    <div>
      <div style={{ margin: "0 0 12px" }} aria-label="Forums monitored">
        {summary.map(f => (
          <a key={f.owner + f.repo} href={`https://github.com/${f.owner}/${f.repo}/discussions`} target="_blank" rel="noopener noreferrer"
             style={{ ...chip, background: f.count === null ? "#FEF5E7" : f.count > 0 ? "#EBF5FB" : "#F4F6F7", color: "#1b2a4f" }}>
            <strong>{f.label}</strong>{" "}
            {f.count === null ? "· no data yet" : `· ${f.count} open`}
          </a>
        ))}
        {offRepos.map(f => (
          <a key={f.owner + f.repo} href={`https://github.com/${f.owner}/${f.repo}`} target="_blank" rel="noopener noreferrer"
             style={{ ...chip, background: "#F4F6F7", color: "#5d6d7e" }}>
            <strong>{f.label}</strong> · Discussions turned off on GitHub
          </a>
        ))}
      </div>
      {noData.length > 0 && (
        <p style={{ color: "#7D6608" }}>
          No data yet for: {noData.join(", ")}. The backend job may not be collecting these repositories yet.
        </p>
      )}
      <div style={{ height: 600, width: "100%" }}>
        <DataGrid
          rowHeight={40}
          getRowId={(row) => row.id}
          rows={data}
          columns={columns}
          getRowClassName={getRowClassName}
          initialState={{
            sorting: { sortModel: [{ field: "hours_waiting", sort: "desc" }] },
            pagination: { paginationModel: { pageSize: 20 } },
          }}
          pageSizeOptions={[10, 20, 50]}
        />
      </div>
    </div>
  );
};

export default ItemDataGrid;
