import React from "react";
import ItemDataGrid from "./ItemDataGrid";
import "./App.css";
import config from "./config";
import { REPOS, TARGET_HOURS, fileFor } from "./discussionsConfig";

// Prepend the bucket to each repository's file
const discussionSources = REPOS.filter(r => !r.discussionsOff).map(r => ({
  ...r,
  url: `${config.discussionsBucket}/${fileFor(r)}`,
}));
const offRepos = REPOS.filter(r => r.discussionsOff);

function ApiDiscussionResults() {
  return (
    <div style={{ padding: 30 }}>
      <div>
        <h1>Discussions</h1>
        <p>Open GitHub discussions without an accepted answer, across the {REPOS.length} forums the support team monitors. Click a forum below to open its Discussions page.</p>
        <p>
          <span style={{ color: '#C0392B', fontWeight: 600 }}>Red</span>: needs a reply (no reply yet, or a user commented last).{" "}
          <span style={{ color: '#1E8449', fontWeight: 600 }}>Green</span>: the support team replied last and is waiting on the user.{" "}
          Grey: started by a support team member.{" "}
          "Waiting" counts from the last comment. Target: a substantive reply or SME contact within {TARGET_HOURS.due} hours (reminder at {TARGET_HOURS.remind}, escalate at {TARGET_HOURS.escalate}).
        </p>
        <p>
          To clear a row, mark the reply as the answer or close the discussion on GitHub.
        </p>
        <ItemDataGrid sources={discussionSources} offRepos={offRepos} />
      </div>
    </div>
  );
}

export default ApiDiscussionResults;
